            // ===== COUNTRY PANAMA =====
paisPanama_nombre: 'Panama',
paisPanama_subtitulo: 'Infinite',
paisPanama_tagline: 'Where the Pacific embraces the Atlantic',
paisPanama_descripcion: 'Engineering marvels, ancestral cultures, virgin rainforests, and remote beaches in an extraordinary territory of 75,517 km². The isthmus that unites two continents and separates two oceans.',
paisPanama_continente: 'Central America',
paisPanama_moneda: 'US Dollar (USD) / Balboa (PAB)',
paisPanama_idioma: 'Spanish',
paisPanama_capital: 'Panama City',
