// ===== MEXICO =====
paisMexico_nombre: 'Mexico',
paisMexico_subtitulo: 'Vibrant',
paisMexico_tagline: 'A country of a thousand cultures, where the past and future meet',
paisMexico_descripcion: 'Mexico is the third largest country in Latin America, with 1.96 million km². Located in northern Central America, it combines lush coasts, deserts, snow-capped mountains, and over 3,000 years of civilizational history. It is the largest economy in the region and the country with the most Spanish speakers in the world.',
paisMexico_continente: 'North America',
paisMexico_moneda: 'Mexican Peso (MXN)',
paisMexico_idioma: 'Spanish (official), 68 recognized indigenous languages',
paisMexico_capital: 'Mexico City (CDMX)',
paisMexico_poblacion: '128,900,000',
paisMexico_zona_horaria: 'UTC−6 to UTC−8 (4 time zones)',
paisMexico_codigo_telefonico: '+52',

