paisCuba_historia_cronologia_0_titulo: 'European arrival',
paisCuba_historia_cronologia_0_texto: 'Christopher Columbus arrives on the island, marking the beginning of Spanish colonization.',
paisCuba_historia_cronologia_1_titulo: 'Foundation of Havana',
paisCuba_historia_cronologia_1_texto: 'Havana is founded in its current location. It became a key port of the Spanish Empire.',
paisCuba_historia_cronologia_2_titulo: 'Beginning of the republic',
