//IDIOMA DE GUATEMALA EN INGLES
// ===== GUATEMALA =====
paisGuatemala_nombre: 'Guatemala',
paisGuatemala_subtitulo: 'Ancestral',
paisGuatemala_tagline: 'Land of volcanoes, living culture, and ancient landscapes',
paisGuatemala_descripcion: 'Guatemala is in Central America and is known for its great cultural and natural diversity. It has an area of 108,889 km², an estimated population of 18.4 million, capital in Guatemala City, quetzal currency, and official language Spanish.',
paisGuatemala_continente: 'Central America',
paisGuatemala_moneda: 'Quetzal (GTQ)',
paisGuatemala_idioma: 'Spanish (official), 22 Mayan languages, Xinca, and Garífuna',
